702	// ---------------------------------------------------------------------------
703	// Strict JSON parser used by `verify`.
704	//
705	// Written by hand so the crate keeps zero third-party runtime dependencies.
706	// Unlike a tolerant parser it enforces every rule the verify contract relies
707	// on: exactly one complete value surrounded only by JSON whitespace, no
708	// duplicate member names within an object, strict number grammar (integers
709	// only, no fractions/exponents/leading zeros), strings decoded per RFC 8259
710	// including surrogate pairs. Anything it cannot parse is a corrupt record
711	// (exit 2), never a mismatch.
712	// ---------------------------------------------------------------------------
713	
714	mod json {
715	    /// An integer written with a legal JSON decimal spelling (optional sign,
716	    /// no leading zero, no fraction or exponent). The spelling is kept rather
717	    /// than the numeric value so integers wider than `i128` stay representable:
718	    /// a version field merely has to tell "1" apart from any other integer,
719	    /// which is a lexical decision and must never truncate or reject the value
720	    /// just because it is too large for the machine's widest integer.
721	    #[derive(Debug, PartialEq, Eq)]
722	    pub enum JsonInt {
723	        /// Integer that fits in `i128`; carries its exact value.
724	        Small(i128),
725	        /// Legal integer spelling that is outside the `i128` range, kept as
726	        /// its exact decimal text (including a leading '-'). Never truncated,
727	        /// rounded or treated as 1.
728	        Large(String),
729	    }
730	
731	    impl JsonInt {
732	        /// Parse a strictly-written JSON integer spelling (the caller has
733	        /// already enforced the grammar, including no leading zeros) without
734	        /// rejecting values wider than `i128`.
735	        fn from_strict_spelling(text: &str) -> JsonInt {
736	            match text.parse::<i128>() {
737	                Ok(n) => JsonInt::Small(n),
738	                // parse only fails here because the magnitude is out of range;
739	                // the spelling itself is valid JSON, so retain it verbatim.
740	                Err(_) => JsonInt::Large(text.to_string()),
741	            }
742	        }
743	
744	        /// Whether the integer is exactly the value 1: true only for the
745	        /// canonical spelling "1" (a `Large` value can never equal 1).
746	        pub fn is_one(&self) -> bool {
747	            matches!(self, JsonInt::Small(1))
748	        }
749	
750	        /// Exact value when it fits in `i128`; out-of-range spellings yield
751	        /// `None` instead of being truncated or wrapped.
752	        pub fn as_i128(&self) -> Option<i128> {
753	            match self {
754	                JsonInt::Small(n) => Some(*n),
755	                JsonInt::Large(_) => None,
756	            }
757	        }
758	    }
759	
760	    #[derive(Debug, PartialEq)]
761	    pub enum JsonValue {
762	        /// Parsed as an integer because the record grammar has no fractional
763	        /// values. Integers beyond `i128` stay legal JSON and are retained as
764	        /// their exact spelling (see `JsonInt::Large`).
765	        Number(JsonInt),
766	        String(String),
767	        Array(Vec<JsonValue>),
768	        /// Members kept in source order; names are unique (parser-enforced).
769	        Object(Vec<(String, JsonValue)>),
770	        // Accepted so documents using them parse, but records containing them
771	        // are rejected structurally by the caller.
772	        Bool(bool),
773	        Null,
774	    }
775	
776	    struct Parser<'a> {
777	        bytes: &'a [u8],
778	        pos: usize,
779	        /// Current object/array nesting depth, capped so adversarial input
780	        /// ("[[[[...")") cannot exhaust the stack and crash the verifier.
781	        depth: usize,
782	    }
783	
784	    /// Far above the depth a real record ever reaches (record → `fields`
785	    /// array → string is depth 2) while staying well within stack limits.
786	    const MAX_DEPTH: usize = 64;
787	
788	    /// Parse exactly one JSON value: optional leading/trailing JSON whitespace
789	    /// is allowed, but any trailing non-whitespace content (including a second
790	    /// object) is an error.
791	    pub fn parse_single(input: &str) -> Result<JsonValue, String> {
792	        let mut p = Parser {
793	            bytes: input.as_bytes(),
794	            pos: 0,
795	            depth: 0,
796	        };
797	        p.skip_ws();
798	        if p.pos == p.bytes.len() {
799	            return Err("input is empty; expected one JSON record".to_string());
800	        }
801	        let value = p.parse_value()?;
802	        p.skip_ws();
803	        if p.pos != p.bytes.len() {
804	            return Err(
805	                "trailing non-whitespace content after record; exactly one JSON object is allowed"
806	                    .to_string(),
807	            );
808	        }
809	        Ok(value)
810	    }
811	
812	    impl<'a> Parser<'a> {
813	        fn skip_ws(&mut self) {
814	            while self.pos < self.bytes.len()
815	                && matches!(self.bytes[self.pos], b' ' | b'\t' | b'\n' | b'\r')
816	            {
817	                self.pos += 1;
818	            }
819	        }
820	
821	        fn peek(&self) -> Option<u8> {
822	            self.bytes.get(self.pos).copied()
823	        }
824	
825	        fn enter_container(&mut self) -> Result<(), String> {
826	            if self.depth >= MAX_DEPTH {
827	                return Err("JSON nesting is too deep".to_string());
828	            }
829	            self.depth += 1;
830	            Ok(())
831	        }
832	
833	        fn parse_value(&mut self) -> Result<JsonValue, String> {
834	            self.skip_ws();
835	            match self.peek() {
836	                Some(b'{') => self.parse_object(),
837	                Some(b'[') => self.parse_array(),
838	                Some(b'"') => Ok(JsonValue::String(self.parse_string()?)),
839	                Some(b't') => self.parse_lit("true", JsonValue::Bool(true)),
840	                Some(b'f') => self.parse_lit("false", JsonValue::Bool(false)),
841	                Some(b'n') => self.parse_lit("null", JsonValue::Null),
842	                Some(c) if c == b'-' || c.is_ascii_digit() => self.parse_number(),
843	                Some(_) => Err("unexpected character while parsing JSON".to_string()),
844	                None => Err("unexpected end of JSON input".to_string()),
845	            }
846	        }
847	
848	        fn parse_lit(&mut self, lit: &str, value: JsonValue) -> Result<JsonValue, String> {
849	            if self.bytes[self.pos..].starts_with(lit.as_bytes()) {
850	                self.pos += lit.len();
851	                Ok(value)
852	            } else {
853	                Err("malformed JSON literal".to_string())
854	            }
855	        }
856	
857	        fn parse_object(&mut self) -> Result<JsonValue, String> {
858	            self.enter_container()?;
859	            let result = self.parse_object_inner();
860	            self.depth -= 1;
861	            result
862	        }
863	
864	        fn parse_object_inner(&mut self) -> Result<JsonValue, String> {
865	            self.pos += 1; // '{'
866	            let mut entries: Vec<(String, JsonValue)> = Vec::new();
867	            self.skip_ws();
868	            if self.peek() == Some(b'}') {
869	                self.pos += 1;
870	                return Ok(JsonValue::Object(entries));
871	            }
872	            loop {
873	                self.skip_ws();
874	                if self.peek() != Some(b'"') {
875	                    return Err("expected a string member name in JSON object".to_string());
876	                }
877	                let name = self.parse_string()?;
878	                self.skip_ws();
879	                if self.peek() != Some(b':') {
880	                    return Err("expected ':' after JSON member name".to_string());
881	                }
882	                self.pos += 1;
883	                let value = self.parse_value()?;
884	                if entries.iter().any(|(n, _)| *n == name) {
885	                    return Err("JSON object contains a duplicate member".to_string());
886	                }
887	                entries.push((name, value));
888	                self.skip_ws();
889	                match self.peek() {
890	                    Some(b',') => {
891	                        self.pos += 1;
892	                    }
893	                    Some(b'}') => {
894	                        self.pos += 1;
895	                        break;
896	                    }
897	                    Some(_) => return Err("expected ',' or '}}' in JSON object".to_string()),
898	                    None => return Err("unterminated JSON object".to_string()),
899	                }
900	            }
901	            Ok(JsonValue::Object(entries))
902	        }
903	
904	        fn parse_array(&mut self) -> Result<JsonValue, String> {
905	            self.enter_container()?;
906	            let result = self.parse_array_inner();
907	            self.depth -= 1;
908	            result
909	        }
910	
911	        fn parse_array_inner(&mut self) -> Result<JsonValue, String> {
912	            self.pos += 1; // '['
913	            let mut items = Vec::new();
914	            self.skip_ws();
915	            if self.peek() == Some(b']') {
916	                self.pos += 1;
917	                return Ok(JsonValue::Array(items));
918	            }
919	            loop {
920	                items.push(self.parse_value()?);
921	                self.skip_ws();
922	                match self.peek() {
923	                    Some(b',') => {
924	                        self.pos += 1;
925	                        self.skip_ws();
926	                    }
927	                    Some(b']') => {
928	                        self.pos += 1;
929	                        break;
930	                    }
931	                    Some(_) => return Err("expected ',' or ']' in JSON array".to_string()),
932	                    None => return Err("unterminated JSON array".to_string()),
933	                }
934	            }
935	            Ok(JsonValue::Array(items))
936	        }
937	
938	        fn parse_string(&mut self) -> Result<String, String> {
939	            self.pos += 1; // opening quote
940	            let mut out = String::new();
941	            loop {
942	                match self.peek() {
943	                    None => return Err("unterminated JSON string".to_string()),
944	                    Some(b'"') => {
945	                        self.pos += 1;
946	                        break;
947	                    }
948	                    Some(b'\\') => {
949	                        self.pos += 1;
950	                        let esc = self
951	                            .peek()
952	                            .ok_or("unterminated JSON escape sequence")?;
953	                        self.pos += 1;
954	                        match esc {
955	                            b'"' => out.push('"'),
956	                            b'\\' => out.push('\\'),
957	                            b'/' => out.push('/'),
958	                            b'b' => out.push('\u{0008}'),
959	                            b'f' => out.push('\u{000c}'),
960	                            b'n' => out.push('\n'),
961	                            b'r' => out.push('\r'),
962	                            b't' => out.push('\t'),
963	                            b'u' => {
964	                                let hi = self.parse_hex4()?;
965	                                let c = if (0xD800..=0xDBFF).contains(&hi) {
966	                                    // High surrogate must be followed by "\uXXXX"
967	                                    // low surrogate; lone surrogates are invalid.
968	                                    if self.peek() != Some(b'\\') {
969	                                        return Err(
970	                                            "lone UTF-16 high surrogate in JSON string".to_string()
971	                                        );
972	                                    }
973	                                    self.pos += 1;
974	                                    if self.peek() != Some(b'u') {
975	                                        return Err(
976	                                            "bad surrogate pair escape in JSON string".to_string()
977	                                        );
978	                                    }
979	                                    self.pos += 1;
980	                                    let lo = self.parse_hex4()?;
981	                                    if !(0xDC00..=0xDFFF).contains(&lo) {
982	                                        return Err(
983	                                            "low surrogate out of range in JSON string".to_string()
984	                                        );
985	                                    }
986	                                    char::from_u32(0x10000 + ((hi - 0xD800) << 10) + (lo - 0xDC00))
987	                                        .ok_or("invalid surrogate pair in JSON string")?
988	                                } else if (0xDC00..=0xDFFF).contains(&hi) {
989	                                    return Err(
990	                                        "lone UTF-16 low surrogate in JSON string".to_string()
991	                                    );
992	                                } else {
993	                                    char::from_u32(hi)
994	                                        .ok_or("invalid unicode escape in JSON string")?
995	                                };
996	                                out.push(c);
997	                            }
998	                            _ => {
999	                                return Err("invalid escape sequence in JSON string".to_string())
1000	                            }
1001	                        }
1002	                    }
1003	                    Some(c) if c < 0x20 => {
1004	                        return Err("unescaped control character in JSON string".to_string())
1005	                    }
1006	                    Some(_) => {
1007	                        // Copy one whole UTF-8 scalar at a time, validating that
1008	                        // the raw bytes really are UTF-8 (the surrounding input
1009	                        // is &str so this cannot fail, but keep the boundary
1010	                        // explicit rather than slicing mid-char).
1011	                        let start = self.pos;
1012	                        self.pos += 1;
1013	                        while self.pos < self.bytes.len() {
1014	                            let b = self.bytes[self.pos];
1015	                            if b == b'"' || b == b'\\' || b < 0x20 {
1016	                                break;
1017	                            }
1018	                            self.pos += 1;
1019	                        }
1020	                        let chunk = std::str::from_utf8(&self.bytes[start..self.pos])
1021	                            .map_err(|_| "invalid UTF-8 inside JSON string".to_string())?;
1022	                        out.push_str(chunk);
1023	                    }
1024	                }
1025	            }
1026	            Ok(out)
1027	        }
1028	
1029	        fn parse_hex4(&mut self) -> Result<u32, String> {
1030	            let mut v = 0u32;
1031	            for _ in 0..4 {
1032	                if self.peek().is_none() {
1033	                    return Err("truncated \\u escape in JSON string".to_string());
1034	                }
1035	                let c = self.peek().unwrap();
1036	                if !(c as char).is_ascii_hexdigit() {
1037	                    return Err("bad hexadecimal digit in \\u escape".to_string());
1038	                }
1039	                let d = (c as char).to_digit(16).unwrap();
1040	                self.pos += 1;
1041	                v = v * 16 + d;
1042	            }
1043	            Ok(v)
1044	        }
1045	
1046	        /// Strict RFC 8259 integer grammar. The record format has no fractional
1047	        /// values, so `.`/`e` forms are rejected rather than truncated. A
1048	        /// syntactically legal integer is never rejected for being wider than
1049	        /// `i128`: it is retained verbatim so callers can classify it (for
1050	        /// example, an unsupported format version) without truncating the
1051	        /// value or confusing it with corrupt JSON.
1052	        fn parse_number(&mut self) -> Result<JsonValue, String> {
1053	            let start = self.pos;
1054	            if self.peek() == Some(b'-') {
1055	                self.pos += 1;
1056	            }
1057	            match self.peek() {
1058	                Some(b'0') => {
1059	                    self.pos += 1;
1060	                    // A leading zero must not be followed by more digits.
1061	                    if matches!(self.peek(), Some(c) if c.is_ascii_digit()) {
1062	                        return Err("numbers with leading zeros are not valid JSON".to_string());
1063	                    }
1064	                }
1065	                Some(c) if c.is_ascii_digit() => {
1066	                    while matches!(self.peek(), Some(c) if c.is_ascii_digit()) {
1067	                        self.pos += 1;
1068	                    }
1069	                }
1070	                _ => return Err("malformed JSON number".to_string()),
1071	            }
1072	            // No fraction or exponent: this grammar only carries integers.
1073	            if matches!(self.peek(), Some(b'.' | b'e' | b'E')) {
1074	                return Err(
1075	                    "record numbers must be integers; fractions and exponents are not accepted"
1076	                        .to_string(),
1077	                );
1078	            }
1079	            let text = std::str::from_utf8(&self.bytes[start..self.pos])
1080	                .map_err(|_| "invalid UTF-8 in JSON number".to_string())?;
1081	            Ok(JsonValue::Number(JsonInt::from_strict_spelling(text)))
1082	        }
1083	    }
1084	}
