1165	    /// Build a format-1 record JSON string for the given content, with the
1166	    /// correct tag for `key`.
1167	    fn record_for(key_hex: &str, key_id: &str, version: u32, fields: &[&str]) -> String {
1168	        let tag = sign_tag(key_hex, key_id, version, fields);
1169	        let fields_json = fields
1170	            .iter()
1171	            .map(|f| format!("\"{}\"", json_escape(f)))
1172	            .collect::<Vec<_>>()
1173	            .join(",");
1174	        format!(
1175	            "{{\"format\":1,\"algorithm\":\"HMAC-SHA256\",\"key_id\":\"{}\",\"key_version\":{},\"fields\":[{}],\"tag\":\"{}\"}}",
1176	            json_escape(key_id),
1177	            version,
1178	            fields_json,
1179	            tag
1180	        )
1181	    }
