1320	            v1.replace("\"key_version\":1", "\"key_version\":4294967295"),
1321	            record_for(key, "id", 4294967295, &["x"])
1322	                .replace(&vmax_tag, &sign_tag(key, "id", 1, &["x"])),
1323	        ];
1324	        for rec in tampered {
1325	            for k in [key, wrong_key] {
1326	                assert!(
1327	                    matches!(verify_input(rec.as_bytes(), k), VerifyOutcome::Mismatch),
1328	                    "expected mismatch for {rec}"
1329	                );
1330	            }
1331	        }
