1567	    fn strict_parser_rules() {
1568	        use json::parse_single;
1569	        assert!(parse_single("{}").is_ok());
1570	        assert!(parse_single(" \n\t {} \r").is_ok());
1571	        assert!(parse_single("{\"a\":1}").is_ok());
