439	#[test]
440	fn verify_illegal_key_version_spellings_are_corrupt_input() {
441	    // None of these may be accepted as integer 7 (or any other integer):
442	    // quoted text, fraction, exponent, leading zero are not JSON integers;
443	    // zero/negative/above-max are out of range; the huge decimal is far beyond
444	    // integer parse range and must not truncate, round or wrap to a valid
445	    // version. Every one is exit 2: empty stdout and a stderr that explains
446	    // the number/version problem without echoing the key, record text or the
447	    // rejected literal. The outcome is identical when a valid-but-wrong key is
448	    // supplied: structural invalidity takes precedence over authentication.
449	    let cases: &[&str] = &[
450	        r#""7""#,                                  // string, not a number
451	        "7.0",                                     // fraction spelling of 7
452	        "7e0",                                     // exponent spelling of 7
453	        "007",                                     // leading zero
454	        "0",                                       // below range
455	        "-0",                                      // parses numerically to 0: still below range
456	        "-1",                                      // negative
457	        "4294967296",                              // one above the max
458	        "99999999999999999999999999999999999999999", // far beyond i128 parsing
459	    ];
460	    for token in cases {
461	        for key in [KV_KEY, KV_WRONG_KEY] {
462	            let out = run_verify(key, kv_record(token, KV_TAG_V1).as_bytes());
463	            assert_eq!(
464	                out.status.code(),
465	                Some(2),
466	                "token {token:?}: expected corrupt input (exit 2), key={key}"
467	            );
468	            assert!(out.stdout.is_empty(), "token {token:?}: stdout must be empty");
469	            let stderr = String::from_utf8(out.stderr).expect("stderr must be UTF-8");
470	            assert!(
471	                !stderr.trim().is_empty(),
472	                "token {token:?}: stderr must explain the problem"
473	            );
474	            let lower = stderr.to_lowercase();
475	            assert!(
476	                lower.contains("number") || lower.contains("integer") || lower.contains("version"),
477	                "token {token:?}: stderr must describe the number/version problem: {stderr}"
478	            );
479	            // Never echo the key, any record text, or the full record.
480	            assert!(!stderr.contains(key), "token {token:?}: stderr echoed the key: {stderr}");
481	            assert!(!stderr.contains(KV_KID), "token {token:?}: stderr echoed key id: {stderr}");
482	            assert!(!stderr.contains(KV_FIELD), "token {token:?}: stderr echoed a field: {stderr}");
483	            assert!(!stderr.contains(KV_TAG_V1), "token {token:?}: stderr echoed the tag/record: {stderr}");
484	
485	            // The same record padded with legal JSON whitespace stays corrupt:
486	            // whitespace cannot launder a bad number spelling.
487	            let padded = format!(" \n\t{}\r\n  ", kv_record(token, KV_TAG_V1));
488	            let out = run_verify(key, padded.as_bytes());
489	            assert_eq!(
490	                out.status.code(),
491	                Some(2),
492	                "token {token:?}: padding must not make it accepted, key={key}"
493	            );
494	            assert!(out.stdout.is_empty());
495	        }
496	    }
497	
498	    // The rejected literal itself must not be quoted back (checked for the
499	    // distinctive spellings whose digits do not legitimately appear in the
500	    // fixed "1..=4294967295" range text).
501	    for token in &[r#""7""#, "7.0", "7e0", "007", "4294967296",
502	                   "99999999999999999999999999999999999999999"] {
503	        for key in [KV_KEY, KV_WRONG_KEY] {
504	            let out = run_verify(key, kv_record(token, KV_TAG_V1).as_bytes());
505	            let stderr = String::from_utf8_lossy(&out.stderr);
506	            assert!(
507	                !stderr.contains(token),
508	                "token {token:?}: stderr echoed the rejected literal: {stderr}"
509	            );
510	        }
511	    }
512	}
