1023	#[derive(Debug)]
1024	struct Record {
1025	    raw: Json,
1026	    format: i64,
1027	    algorithm: String,
1028	    key_id: String,
1029	    key_version: i64,
1030	    fields: Vec<String>,
1031	    tag: String,
1032	}
