1286	/// Run the same signing twice and return both records' parsed form plus the
1287	/// exact stdout bytes, for determinism comparisons.
1288	fn sign_twice(key: &str, key_id: &str, version: &str, fields: &[&str]) -> (Record, Record, Vec<u8>, Vec<u8>) {
1289	    let out1 = run_sign(key, key_id, version, fields);
1290	    let out2 = run_sign(key, key_id, version, fields);
1291	    assert_eq!(out1.status.code(), Some(0));
1292	    assert_eq!(out2.status.code(), Some(0));
1293	    assert!(out1.stderr.is_empty() && out2.stderr.is_empty());
1294	    (
1295	        parse_single_record(&out1.stdout),
1296	        parse_single_record(&out2.stdout),
1297	        out1.stdout,
1298	        out2.stdout,
1299	    )
1300	}
