1504	fn separated_equals_and_mixed_spellings_produce_identical_records() {
1505	    // The same invocation written three ways: every option separated, every
1506	    // option inline with '=', and the two spellings alternating. The fields
1507	    // exercise Chinese, a real newline, leading/trailing whitespace, embedded
1508	    // '=' (a=b=c), a repeated value and a trailing empty field.
1509	    let separated: &[&str] = &[
1510	        "--key", "00ff", "--key-id", "id", "--key-version", "1",
1511	        "--field", "世界",
1512	        "--field", "\n换行 ",
1513	        "--field", " a=b=c ",
1514	        "--field", "x",
1515	        "--field", "x",
1516	        "--field", "",
1517	    ];
1518	    let inline: &[&str] = &[
1519	        "--key=00ff", "--key-id=id", "--key-version=1",
1520	        "--field=世界",
1521	        "--field=\n换行 ",
1522	        "--field= a=b=c ",
1523	        "--field=x",
1524	        "--field=x",
1525	        "--field=",
1526	    ];
1527	    let mixed: &[&str] = &[
1528	        "--key=00ff", "--key-id", "id", "--key-version=1",
1529	        "--field", "世界",
1530	        "--field=\n换行 ",
1531	        "--field", " a=b=c ",
1532	        "--field=x",
1533	        "--field", "x",
1534	        "--field=",
1535	    ];
1536	    let (rec, raw) =
1537	        expect_equivalent_spellings("all-four-options", &[separated, inline, mixed]);
