1545	    assert_eq!(rec.key_version, 1);
1546	    assert_eq!(
1547	        rec.fields,
1548	        vec![
1549	            "世界".to_string(),
1550	            "\n换行 ".to_string(),
1551	            " a=b=c ".to_string(),
1552	            "x".to_string(),
1553	            "x".to_string(),
1554	            String::new(),
1555	        ]
1556	    );
1557	    // Mixing spellings neither reorders fields, merges the duplicate "x", nor
1558	    // drops the trailing empty field: all six survive in argv order.
1559	    assert_eq!(rec.fields.len(), 6);
1560	
1561	    // The whitespace and the embedded '=' survive on the wire untrimmed.
1562	    let text = String::from_utf8(raw).unwrap();
