1565	    // The actual key feeds only the MAC; it is not a record value.
1566	    let mut strings = Vec::new();
1567	    rec.raw.strings(&mut strings);
1568	    assert!(
1569	        strings.iter().all(|s| s != "00ff"),
1570	        "the raw key must not appear as a record value: {strings:?}"
1571	    );
