2108	// verify: records hand-authored as if produced by an *external* program that
2109	// only knows the published format 1 contract.
2110	//
2111	// `sign` is never invoked in this section, so a shared bug in this crate's
2112	// sign/verify pair cannot make these tests pass. Every tag is a golden value
2113	// computed independently with Python's hmac/hashlib/struct straight from the
2114	// byte recipe printed in README.md:
2115	//
2116	//   import hmac, hashlib, struct
2117	//   def encode(key_id, version, fields):
2118	//       out = b"authnote-sign-v1"
2119	//       kb = key_id.encode()
2120	//       out += struct.pack(">Q", len(kb)) + kb
2121	//       out += struct.pack(">I", version)
2122	//       out += struct.pack(">Q", len(fields))
2123	//       for f in fields:
2124	//           fb = f.encode()
2125	//           out += struct.pack(">Q", len(fb)) + fb
2126	//       return out
2127	//   hmac.new(bytes.fromhex(key), encode(key_id, version, fields),
2128	//            hashlib.sha256).hexdigest()
2129	//
2130	// The authenticated content exercises what cannot travel through a command
2131	// line: a NUL (U+0000) flanked by text inside a field, plus Chinese, emoji
2132	// (including a UTF-16 surrogate pair spelling) and real newlines.
2133	// ---------------------------------------------------------------------------
