2136	/// Independent Python golden tag over:
2137	/// key `cafecafe...cafe`, key_id `密钥\n🙂`, version 42,
2138	/// fields [`前\u{0000}后`, `世界🙂\n第二行`, ``, `世界🙂\n第二行`].
2139	const EXT_KEY: &str = "cafecafecafecafecafecafecafecafe";
2140	const EXT_TAG: &str = "7474105d623bb03a81eb00b34545fcaf7a8c24002c5a6e58ecfdc6172e1d7f9c";
