2145	/// Golden tag for key_id `外部记录`, version 1, one field containing only NUL.
2146	const EXT2_NUL_TAG: &str = "cc556672a3f98087fd6dac8c8a8121f517101f784cb7d163cbe4aea5dfbfc559";
2147	/// Golden tag for the same record with the field being the empty string.
