2383	// ---------------------------------------------------------------------------
2384	// verify: member names are recognized by their JSON-decoded text
2385	//
2386	// An external program that saves or re-formats a record may spell a member
2387	// name with \u escapes; the name is recognized by its decoded text, so the
2388	// rewrite stays valid. The same decoding rule makes two spellings of one
2389	// decoded name a duplicate member (exit 2), and never promotes a look-alike
2390	// name (different case, surrounding whitespace, extra characters) into a
2391	// known member.
2392	// ---------------------------------------------------------------------------
2393	
2394	/// Overwrite the spelling of one member name inside a compact signed record.
2395	/// `spelling` is the raw JSON text of the replacement name (without the
2396	/// quotes), so escape sequences can be supplied exactly as they appear on
2397	/// the wire.
2398	fn respell_member(record: &str, canonical: &str, spelling: &str) -> String {
2399	    let needle = format!("\"{canonical}\":");
2400	    assert_eq!(
2401	        record.matches(&needle).count(),
2402	        1,
2403	        "record must contain member {canonical} exactly once: {record}"
2404	    );
2405	    record.replacen(&needle, &format!("\"{spelling}\":"), 1)
2406	}
